-- Give Stock disponible utilisable the same filters as the issue and receiving reports: Geographic
-- Level, Geographic Zone, Facility Type and Product, a facility list that rolls up child zones, and
-- the same header.

UPDATE report.jasper_templates
SET data = '\'
WHERE id = '0de91367-bdfb-4a02-8b66-40770b1f8ad6';

UPDATE report.template_parameters
SET selectexpression = '/api/facilities?recurse=true'
WHERE id = 'b3b75270-ec7b-4eec-8ea3-aa4ee87bd4f7';

